//! Safe Rust bindings for the Kylin coreai-embedding SDK (text only).
//!
//! Uses [`libloading`] to load `libkysdk-coreai-embedding.so` at runtime so the
//! workspace still builds and runs on hosts without the SDK installed. Type
//! definitions are generated by bindgen.
//!
//! # Library search order
//!
//! 1. `KART_EMBEDDING_SDK_PATH` environment variable (full path to .so)
//! 2. System library path matching the build target architecture
//! 3. Next to the running binary (deployment)
//! 4. Bare SONAME — defers to the dynamic linker (ldconfig / `LD_LIBRARY_PATH`)
//!
//! # Safety
//!
//! This crate is the only place where `unsafe` is permitted for the
//! coreai-embedding SDK. All `unsafe` is confined to `extern "C"` call sites;
//! the public API is fully safe Rust.

#[cfg(not(feature = "stub"))]
use std::ffi::{CStr, CString};
#[cfg(not(feature = "stub"))]
use std::os::raw::{c_char, c_int};
#[cfg(not(feature = "stub"))]
use std::path::PathBuf;
use std::sync::Mutex;
#[cfg(not(feature = "stub"))]
use std::sync::OnceLock;

use libloading::Library;
#[cfg(not(feature = "stub"))]
use libloading::Symbol;
use thiserror::Error;

// ── Bindings ────────────────────────────────────────────────────────────────

#[cfg(not(feature = "stub"))]
#[allow(nonstandard_style, unused)]
mod bindings;

#[cfg(not(feature = "stub"))]
pub use bindings::{
    EmbeddingModelInfo, EmbeddingModelList, EmbeddingResult, TextEmbeddingResultCallback,
    TextEmbeddingSession,
};

// Stub mode: provide minimal opaque type aliases so downstream code still
// type-checks. All callable surface returns LibraryNotFound at runtime.
#[cfg(feature = "stub")]
#[allow(non_camel_case_types)]
pub enum TextEmbeddingSession {}
#[cfg(feature = "stub")]
#[allow(non_camel_case_types)]
pub enum EmbeddingResult {}
#[cfg(feature = "stub")]
#[allow(non_camel_case_types)]
pub enum EmbeddingModelList {}
#[cfg(feature = "stub")]
#[allow(non_camel_case_types)]
pub enum EmbeddingModelInfo {}

/// Default text embedding model shipped by the Kylin SDK (gte-base, uint8-quantized).
///
/// Output dimension is 768. Callers may pass a different model name to
/// [`KylinTextEmbedding::new`] after consulting the SDK model list.
pub const DEFAULT_TEXT_MODEL: &str = "ensemble-embd_gte-base_uint8-text";

// ── Errors ──────────────────────────────────────────────────────────────────

#[derive(Debug, Error)]
pub enum KylinEmbeddingError {
    #[error("libkysdk-coreai-embedding not found — install libkylin-coreai-embedding-dev or set KART_EMBEDDING_SDK_PATH")]
    LibraryNotFound,

    #[error("Failed to create embedding session")]
    SessionCreateFailed,

    #[error("Embedding session init failed (code {0})")]
    InitFailed(i32),

    #[error("Model init failed for {model:?} (code {code})")]
    ModelInitFailed { model: String, code: i32 },

    #[error("Unknown model {0:?} — not present in SDK model list")]
    UnknownModel(String),

    #[error("Invalid input: {0}")]
    InvalidInput(String),

    #[error("SDK error (code {0}): {1}")]
    SdkError(i32, String),

    #[error("SDK returned empty embedding result")]
    EmptyResult,

    #[error("SDK function not found in library: {0}")]
    FunctionNotFound(String),
}

pub type Result<T> = std::result::Result<T, KylinEmbeddingError>;

// ── Library loading ─────────────────────────────────────────────────────────

#[cfg(not(feature = "stub"))]
static EMBEDDING_LIB: OnceLock<Option<Library>> = OnceLock::new();

#[cfg(not(feature = "stub"))]
fn lib() -> Option<&'static Library> {
    EMBEDDING_LIB
        .get_or_init(|| {
            // Debian/Kylin multiarch layout. Pick the triple matching the build
            // target at compile time so we only try paths that can plausibly
            // exist for this binary's architecture.
            const SYSTEM_LIB: &str = env!("KART_EMBEDDING_SYSTEM_LIB");

            let candidates: Vec<PathBuf> = vec![
                std::env::var("KART_EMBEDDING_SDK_PATH")
                    .ok()
                    .map(PathBuf::from)
                    .unwrap_or_default(),
                PathBuf::from(SYSTEM_LIB),
                std::env::current_exe()
                    .ok()
                    .and_then(|e| e.parent().map(|d| d.join("libkysdk-coreai-embedding.so")))
                    .unwrap_or_default(),
                PathBuf::from("libkysdk-coreai-embedding.so"),
            ];

            for path in &candidates {
                if path.as_os_str().is_empty() {
                    continue;
                }
                match unsafe { Library::new(path) } {
                    Ok(lib) => {
                        // Verify the library actually exports the symbols we
                        // need before committing to it.
                        let valid = unsafe {
                            lib.get::<unsafe extern "C" fn() -> *mut TextEmbeddingSession>(
                                b"text_embedding_create_session\0",
                            )
                            .is_ok()
                        };
                        if valid {
                            tracing::debug!(
                                "[kart-embedding-sys] loaded library from {}",
                                path.display()
                            );
                            return Some(lib);
                        }
                        tracing::warn!(
                            "[kart-embedding-sys] {} loaded but symbols missing — not a valid SDK",
                            path.display()
                        );
                    }
                    Err(e) => {
                        tracing::debug!(
                            "[kart-embedding-sys] could not load {}: {}",
                            path.display(),
                            e
                        );
                    }
                }
            }
            None
        })
        .as_ref()
}

#[cfg(feature = "stub")]
fn lib() -> Option<&'static Library> {
    None
}

/// Returns true if the SDK library was found and exports the expected symbols.
pub fn is_available() -> bool {
    lib().is_some()
}

// ── Symbol helpers ──────────────────────────────────────────────────────────

#[cfg(not(feature = "stub"))]
fn sym<'lib, T>(lib: &'lib Library, name: &[u8]) -> Result<Symbol<'lib, T>> {
    unsafe { lib.get::<T>(name) }.map_err(|_| {
        KylinEmbeddingError::FunctionNotFound(
            String::from_utf8_lossy(name.trim_ascii_end()).into_owned(),
        )
    })
}

// ── Public safe wrapper ─────────────────────────────────────────────────────

/// Safe RAII handle over a text-embedding session.
///
/// Constructed via [`KylinTextEmbedding::new`], which: creates the SDK session,
/// initializes it, loads the requested model, and queries the model's output
/// dimension. Embedding calls are synchronous; wrap in
/// `tokio::task::spawn_blocking` from async contexts.
pub struct KylinTextEmbedding {
    // `session` is only touched on non-stub paths; in stub mode `new()` errors
    // out before the struct is ever constructed.
    #[cfg_attr(feature = "stub", allow(dead_code))]
    session: Mutex<*mut TextEmbeddingSession>,
    dim: usize,
    model_name: String,
}

// SAFETY: The raw session pointer is wrapped in a Mutex, so concurrent access
// is serialized. The SDK session is owned exclusively by this handle and is
// only accessed through the Mutex guard.
unsafe impl Send for KylinTextEmbedding {}
unsafe impl Sync for KylinTextEmbedding {}

impl KylinTextEmbedding {
    /// Load `model_name` and return a ready-to-use session.
    ///
    /// Looks up the model's output dimension from the SDK's model list so the
    /// caller doesn't have to hard-code it.
    pub fn new(model_name: &str) -> Result<Self> {
        #[cfg(feature = "stub")]
        {
            let _ = model_name;
            Err(KylinEmbeddingError::LibraryNotFound)
        }

        #[cfg(not(feature = "stub"))]
        {
            let lib = lib().ok_or(KylinEmbeddingError::LibraryNotFound)?;

            let model_cstr = CString::new(model_name)
                .map_err(|e| KylinEmbeddingError::InvalidInput(e.to_string()))?;

            // 1. Create session
            let create: Symbol<unsafe extern "C" fn() -> *mut TextEmbeddingSession> =
                sym(lib, b"text_embedding_create_session\0")?;
            let session = unsafe { create() };
            if session.is_null() {
                return Err(KylinEmbeddingError::SessionCreateFailed);
            }

            // From here on, on any error we must destroy the session before
            // returning. We use a small guard struct to keep that automatic.
            let mut guard = SessionGuard {
                session,
                lib,
                disarm: false,
            };

            // 2. Init session
            let init: Symbol<unsafe extern "C" fn(*mut TextEmbeddingSession) -> c_int> =
                sym(lib, b"text_embedding_init_session\0")?;
            let rc = unsafe { init(guard.session) };
            if rc != 0 {
                return Err(KylinEmbeddingError::InitFailed(rc));
            }

            // 3. Init model
            let init_model: Symbol<
                unsafe extern "C" fn(*mut TextEmbeddingSession, *const c_char) -> c_int,
            > = sym(lib, b"text_embedding_init_model\0")?;
            let rc = unsafe { init_model(guard.session, model_cstr.as_ptr()) };
            if rc != 0 {
                return Err(KylinEmbeddingError::ModelInitFailed {
                    model: model_name.to_string(),
                    code: rc,
                });
            }

            // 4. Look up dimension from the SDK's model list. Listing is cheap
            //    (the list lifetime is tied to the session).
            let dim = query_model_dim(lib, guard.session, model_name)?;

            guard.disarm = true;
            Ok(Self {
                session: Mutex::new(guard.session),
                dim,
                model_name: model_name.to_string(),
            })
        }
    }

    /// Output vector dimension for the loaded model (e.g. 768 for the default).
    pub fn dim(&self) -> usize {
        self.dim
    }

    /// The model name that was loaded.
    pub fn model_name(&self) -> &str {
        &self.model_name
    }

    /// Embed a single text into a `Vec<f32>` of length [`Self::dim`].
    ///
    /// Synchronous and CPU/IO bound — wrap in `spawn_blocking` from async code.
    pub fn embed(&self, text: &str) -> Result<Vec<f32>> {
        #[cfg(feature = "stub")]
        {
            let _ = text;
            Err(KylinEmbeddingError::LibraryNotFound)
        }

        #[cfg(not(feature = "stub"))]
        {
            let lib = lib().ok_or(KylinEmbeddingError::LibraryNotFound)?;

            let text_cstr =
                CString::new(text).map_err(|e| KylinEmbeddingError::InvalidInput(e.to_string()))?;

            let embed: Symbol<
                unsafe extern "C" fn(
                    *mut TextEmbeddingSession,
                    *const c_char,
                    *mut *mut EmbeddingResult,
                ) -> bool,
            > = sym(lib, b"text_embedding\0")?;

            let mut result_ptr: *mut EmbeddingResult = std::ptr::null_mut();
            let session = self.session.lock().map_err(|_| {
                KylinEmbeddingError::InvalidInput("session mutex poisoned".to_string())
            })?;
            let ok = unsafe { embed(*session, text_cstr.as_ptr(), &mut result_ptr) };
            if !ok || result_ptr.is_null() {
                // Make sure we don't leak even if the SDK populated result_ptr
                // on the failure path.
                if !result_ptr.is_null() {
                    destroy_result(lib, &mut result_ptr);
                }
                return Err(KylinEmbeddingError::SdkError(
                    -1,
                    "text_embedding returned false".to_string(),
                ));
            }

            let get_err: Symbol<unsafe extern "C" fn(*mut EmbeddingResult) -> c_int> =
                sym(lib, b"embedding_result_get_error_code\0")?;
            let get_msg: Symbol<unsafe extern "C" fn(*mut EmbeddingResult) -> *const c_char> =
                sym(lib, b"embedding_result_get_error_message\0")?;
            let get_vec: Symbol<unsafe extern "C" fn(*mut EmbeddingResult) -> *mut f32> =
                sym(lib, b"embedding_result_get_vector_data\0")?;
            let get_len: Symbol<unsafe extern "C" fn(*mut EmbeddingResult) -> c_int> =
                sym(lib, b"embedding_result_get_vector_length\0")?;

            let code = unsafe { get_err(result_ptr) };
            if code != 0 {
                let msg = unsafe {
                    let ptr = get_msg(result_ptr);
                    if ptr.is_null() {
                        String::new()
                    } else {
                        CStr::from_ptr(ptr).to_string_lossy().into_owned()
                    }
                };
                destroy_result(lib, &mut result_ptr);
                return Err(KylinEmbeddingError::SdkError(code, msg));
            }

            let len = unsafe { get_len(result_ptr) };
            let data_ptr = unsafe { get_vec(result_ptr) };
            if data_ptr.is_null() || len <= 0 {
                destroy_result(lib, &mut result_ptr);
                return Err(KylinEmbeddingError::EmptyResult);
            }

            // SAFETY: SDK guarantees `data_ptr` points to `len` f32s for the
            // lifetime of `result_ptr`. We copy out before destroying.
            let slice = unsafe { std::slice::from_raw_parts(data_ptr, len as usize) };
            let out = slice.to_vec();

            destroy_result(lib, &mut result_ptr);
            Ok(out)
        }
    }
}

#[cfg(not(feature = "stub"))]
fn destroy_result(lib: &Library, result_ptr: &mut *mut EmbeddingResult) {
    if result_ptr.is_null() {
        return;
    }
    if let Ok(f) = unsafe {
        lib.get::<unsafe extern "C" fn(*mut *mut EmbeddingResult)>(b"embedding_result_destroy\0")
    } {
        unsafe { f(result_ptr as *mut _) };
    }
}

#[cfg(not(feature = "stub"))]
fn query_model_dim(
    lib: &Library,
    session: *mut TextEmbeddingSession,
    wanted: &str,
) -> Result<usize> {
    let get_list: Symbol<
        unsafe extern "C" fn(*mut TextEmbeddingSession, *mut c_int) -> *mut EmbeddingModelList,
    > = sym(lib, b"text_embedding_get_model_list\0")?;
    let list_count: Symbol<unsafe extern "C" fn(*const EmbeddingModelList, *mut c_int) -> c_int> =
        sym(lib, b"embedding_model_list_get_count\0")?;
    let list_get: Symbol<
        unsafe extern "C" fn(
            *const EmbeddingModelList,
            c_int,
            *mut c_int,
        ) -> *const EmbeddingModelInfo,
    > = sym(lib, b"embedding_model_list_get_model\0")?;
    let info_name: Symbol<
        unsafe extern "C" fn(*const EmbeddingModelInfo, *mut c_int) -> *const c_char,
    > = sym(lib, b"embedding_model_info_get_model_name\0")?;
    let info_dim: Symbol<unsafe extern "C" fn(*const EmbeddingModelInfo, *mut c_int) -> c_int> =
        sym(lib, b"embedding_model_info_get_model_dim\0")?;

    let mut err: c_int = 0;
    let list = unsafe { get_list(session, &mut err) };
    if list.is_null() || err != 0 {
        return Err(KylinEmbeddingError::SdkError(
            err,
            "text_embedding_get_model_list failed".to_string(),
        ));
    }

    let mut err: c_int = 0;
    let count = unsafe { list_count(list, &mut err) };
    if err != 0 || count <= 0 {
        return Err(KylinEmbeddingError::UnknownModel(wanted.to_string()));
    }

    for i in 0..count {
        let mut err: c_int = 0;
        let info = unsafe { list_get(list, i, &mut err) };
        if info.is_null() || err != 0 {
            continue;
        }
        let mut err: c_int = 0;
        let name_ptr = unsafe { info_name(info, &mut err) };
        if name_ptr.is_null() || err != 0 {
            continue;
        }
        let name = unsafe { CStr::from_ptr(name_ptr) }.to_string_lossy();
        if name == wanted {
            let mut err: c_int = 0;
            let dim = unsafe { info_dim(info, &mut err) };
            if err != 0 || dim <= 0 {
                return Err(KylinEmbeddingError::SdkError(
                    err,
                    "embedding_model_info_get_model_dim returned non-positive".to_string(),
                ));
            }
            return Ok(dim as usize);
        }
    }

    Err(KylinEmbeddingError::UnknownModel(wanted.to_string()))
}

impl Drop for KylinTextEmbedding {
    fn drop(&mut self) {
        #[cfg(not(feature = "stub"))]
        {
            if let Some(lib) = lib() {
                if let Ok(f) = unsafe {
                    lib.get::<unsafe extern "C" fn(*mut *mut TextEmbeddingSession)>(
                        b"text_embedding_destroy_session\0",
                    )
                } {
                    // get_mut() is safe because we have &mut self (exclusive access).
                    if let Ok(session) = self.session.get_mut() {
                        unsafe { f(session) };
                    }
                }
            }
        }
    }
}

// RAII helper used inside `new()` to clean up a half-constructed session on
// the early-return paths.
#[cfg(not(feature = "stub"))]
struct SessionGuard<'lib> {
    session: *mut TextEmbeddingSession,
    lib: &'lib Library,
    disarm: bool,
}

#[cfg(not(feature = "stub"))]
impl Drop for SessionGuard<'_> {
    fn drop(&mut self) {
        if self.disarm || self.session.is_null() {
            return;
        }
        if let Ok(f) = unsafe {
            self.lib
                .get::<unsafe extern "C" fn(*mut *mut TextEmbeddingSession)>(
                    b"text_embedding_destroy_session\0",
                )
        } {
            unsafe { f(&mut self.session) };
        }
    }
}

// ── Tests ───────────────────────────────────────────────────────────────────

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn is_available_does_not_panic() {
        let _ = is_available();
    }

    #[test]
    fn default_model_constant() {
        assert_eq!(DEFAULT_TEXT_MODEL, "ensemble-embd_gte-base_uint8-text");
    }

    #[test]
    fn error_display_library_not_found() {
        let e = KylinEmbeddingError::LibraryNotFound;
        assert!(e.to_string().contains("libkysdk-coreai-embedding"));
    }

    #[test]
    fn error_display_init_failed() {
        let e = KylinEmbeddingError::InitFailed(-7);
        assert!(e.to_string().contains("-7"));
    }

    #[test]
    fn error_display_model_init_failed() {
        let e = KylinEmbeddingError::ModelInitFailed {
            model: "x".into(),
            code: 3,
        };
        let s = e.to_string();
        assert!(s.contains("\"x\""));
        assert!(s.contains("3"));
    }
}
